let saved;try{saved=JSON.parse(localStorage.getItem('airbnb-automation-demo-v1')||'null')}catch{}let state={...structuredClone(defaults),...saved};let current=location.hash.slice(1)||'overview',selectedProperty='all',selectedThread=1,taskView='Board',calendarOffset=0,calendarMode='Timeline',inboxFilter='All',propertyTab='Overview',activeProperty='desert',mobileOpen=false,dayView='Today';
const prop=id=>properties.find(p=>p.id===id)||properties[0];const listProps=()=>selectedProperty==='all'?properties:properties.filter(p=>p.id===selectedProperty);const save=()=>{try{localStorage.setItem('airbnb-automation-demo-v1',JSON.stringify(state))}catch{}};const badge=(text,color='')=>`<span class="badge ${color}">${esc(text)}</span>`;const btn=(text,action,icon='',cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${icon?I(icon):''}${text}</button>`;
