document.addEventListener('click',e=>{const target=e.target.closest('[data-go],[data-action],[data-property],[data-day],[data-filter-property]');if(!target)return;if(target.dataset.go){close();go(target.dataset.go)}else if(target.dataset.property){activeProperty=target.dataset.property;propertyTab='Overview';close();go('property')}else if(target.dataset.day){dayView=target.dataset.day;render()}else if(target.dataset.filterProperty){selectedProperty=target.dataset.filterProperty;close();render();toast(selectedProperty==='all'?'Showing all properties':`Switched to ${prop(selectedProperty).name}`)}else if(actions[target.dataset.action])actions[target.dataset.action](target)});
document.addEventListener('input',e=>{if(e.target.id==='command-search')document.getElementById('command-results').innerHTML=commandResults(e.target.value)});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();command()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=button][data-property]')){e.preventDefault();e.target.click()}});document.getElementById('modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});window.addEventListener('hashchange',()=>{current=location.hash.slice(1)||'overview';render()});
