const threads=[{id:1,p:'desert',name:'Sarah Mitchell',initials:'SM',status:'Needs approval',intent:'Special request',preview:'Would a noon checkout be possible?',question:'We’ve had such a lovely stay! Our flight isn’t until the evening tomorrow. Would it be possible to check out at noon instead of 11?',draft:'Hi Sarah! I’m so glad you’ve enjoyed your stay. A noon checkout tomorrow works perfectly — our cleaning team is scheduled for 12:30 PM. Enjoy a slow morning, and safe travels home!',date:'Sep 12 – 15',channel:'Airbnb'},{id:2,p:'coast',name:'Emily Chen',initials:'EC',status:'Needs approval',intent:'Early check-in',preview:'Could we arrive a little earlier?',question:'Hi! We’ll be driving in with the kids. Could we possibly check in at 2 PM rather than 3 PM?',draft:'Hi Emily! We’re looking forward to welcoming you. The cleaning team expects to finish at 2 PM. I can confirm an early check-in as soon as the final inspection is complete, and I’ll message you when it’s ready.',date:'Sep 14 – 19',channel:'Airbnb'},{id:3,p:'cabin',name:'Oliver Johnson',initials:'OJ',status:'AI handled',intent:'Routine question',preview:'Thanks, that’s exactly what I needed!',question:'Is there a good place nearby to grab coffee in the morning?',draft:'Absolutely! Try Moonridge Coffee, a short drive from the cabin. You’ll also find a few of our favorites in the local guide. Enjoy your stay!',date:'Sep 15 – 19',channel:'Vrbo'},{id:4,p:'coast',name:'Anna Wilson',initials:'AW',status:'Escalated',intent:'Booking modification',preview:'We may need to change our travel dates.',question:'Our plans have changed. Would it be possible to move our stay to the following weekend?',draft:'Hi Anna, thank you for letting me know. I’ll review availability for the following weekend and get back to you with the options. Please keep your existing reservation until we confirm the change.',date:'Sep 22 – 26',channel:'Booking.com'}];
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});const money=n=>'$'+n.toLocaleString('en-US');
const field=(label,name,type='text',value='',extra='')=>`<label class="field">${label}<input class="input" name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;const propertySelect=(name='property',value=activeProperty)=>`<label class="field">Property<select name="${name}">${properties.map(p=>`<option value="${p.id}" ${value===p.id?'selected':''}>${p.name}</option>`).join('')}</select></label>`;const toggle=(key,on,group='rules')=>`<button class="toggle ${on?'on':''}" role="switch" aria-checked="${on}" aria-label="${key}" data-action="toggle" data-key="${key}" data-group="${group}"></button>`;
function calendar(){const start=new Date(2026,8,14+calendarOffset);const dates=Array.from({length:14},(_,i)=>new Date(start.getFullYear(),start.getMonth(),start.getDate()+i));const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const all=[...bookings,...state.blocks.map(b=>({...b,guest:b.reason,channel:'Manual'}))];return `${pageHeader('One calendar. Every channel.','A clear view of every arrival, departure, and moment in between.',btn('Block dates','new-block','plus','btn-primary'))}<div class="toolbar"><div class="flex">${btn('','prev-week','chevron','','aria-label="Previous two weeks" style="transform:rotate(180deg)"')}<h3 style="font-size:15px">${start.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h3>${btn('','next-week','chevron','','aria-label="Next two weeks"')}${btn('Today','calendar-today')}</div><div class="flex"><select id="calendar-property" aria-label="Calendar property"><option value="all">All properties</option>${properties.map(p=>`<option value="${p.id}" ${selectedProperty===p.id?'selected':''}>${p.name}</option>`).join('')}</select>${btn('Sync now','sync','sync')}</div></div><section class="panel"><div class="calendar-scroll"><div class="timeline"><div class="timeline-head"><div>Property <span class="muted">/ ${listProps().length}</span></div>${dates.map(d=>`<div class="${iso(d)==='2026-09-14'?'today':''}">${d.toLocaleDateString('en-US',{weekday:'short'})}<b>${d.getDate()}</b></div>`).join('')}</div>${listProps().map(p=>`<div class="timeline-row"><div class="timeline-label"><b>${p.name}</b><small>${p.place.split(',')[0]} · ${p.beds} bedrooms</small></div>${dates.map((d,i)=>`<button class="day-cell" style="grid-column:${i+2}" aria-label="Block ${p.name} on ${dateLabel(iso(d))}" data-action="new-block" data-p="${p.id}" data-date="${iso(d)}"></button>`).join('')}${all.filter(b=>b.p===p.id).map(b=>{const f=Math.round((new Date(b.from+'T12:00:00')-new Date(iso(start)+'T12:00:00'))/86400000),t=Math.round((new Date(b.to+'T12:00:00')-new Date(iso(start)+'T12:00:00'))/86400000);if(t<=0||f>=14)return '';return `<button class="booking ${b.channel==='Vrbo'?'vrbo':b.channel==='Booking.com'?'bookingcom':b.channel==='Manual'?'manual':''}" style="grid-column:${Math.max(f,0)+2} / ${Math.min(t,14)+2}" data-action="booking" data-id="${b.id}" title="${esc(b.guest)} · ${b.channel} · ${dateLabel(b.from)}–${dateLabel(b.to)} · ${b.channel==='Manual'?'Manual block':'Confirmed; turnover assigned'}">${b.channel==='Manual'?'▧ ':''}${esc(b.guest)}</button>`}).join('')}</div>`).join('')}</div></div><div class="calendar-legend"><span><i></i>Airbnb</span><span><i style="background:#bbc9ed"></i>Vrbo</span><span><i style="background:#b7d6e8"></i>Booking.com</span><span><i style="background:#c3c6c4"></i>Manual block</span><span style="margin-left:auto">${I('shield')} No conflicts</span></div></section><div class="calendar-hint">${I('plus')} Select an empty date to add a block. Select a reservation to see its details.</div><section class="panel"><div class="panel-heading"><h2>Upcoming turnovers</h2>${badge('Automatically scheduled','green')}</div>${state.tasks.filter(t=>t.type==='Turnover').map(t=>`<div class="list-row">${I('sparkle')}<div class="grow"><b>${prop(t.p).name}</b><p>${t.time} · ${t.person}</p></div>${badge(t.status,t.status==='Done'?'green':'blue')}${btn('View task','open-task','arrow','','data-id="'+t.id+'"')}</div>`).join('')}</section>${footer()}`}
function inbox(){const t=threads.find(t=>t.id===selectedThread)||threads[0];const approved=state.approved.includes(t.id)||t.status==='AI handled';return `${pageHeader('Conversations, beautifully connected.','A personal touch for every guest. A little help from AI.',btn('Message templates','templates','file'))}<section class="panel inbox-layout"><aside class="thread-list"><div class="thread-search"><select id="inbox-filter" aria-label="Filter conversations">${['All','Needs approval','AI handled','Escalated'].map(f=>`<option ${inboxFilter===f?'selected':''}>${f}</option>`).join('')}</select></div>${threads.filter(x=>(selectedProperty==='all'||x.p===selectedProperty)&&(inboxFilter==='All'||(state.approved.includes(x.id)?'AI handled':x.status)===inboxFilter)).map(x=>`<button class="thread ${t.id===x.id?'selected':''}" data-action="thread" data-id="${x.id}"><div class="avatar" style="background:${x.id%2?'#e9ded0':'#dae6e2'}">${x.initials}</div><div class="grow"><div class="flex between"><b>${x.name}</b><small>${x.id*4}m</small></div><small>${prop(x.p).name}</small><p>${x.preview}</p><div style="margin-top:8px">${badge(state.approved.includes(x.id)?'Replied':x.status,state.approved.includes(x.id)||x.status==='AI handled'?'green':x.status==='Escalated'?'red':'amber')}</div></div></button>`).join('')}</aside><div class="conversation"><div class="conversation-head"><div class="avatar">${t.initials}</div><div class="grow"><h3>${t.name}</h3><p>${t.channel} · ${prop(t.p).name}</p></div>${badge(t.intent,t.status==='Escalated'?'red':'blue')}</div><div class="chat-body"><div class="chat-date">Monday, September 14</div><div class="bubble host">Hi ${t.name.split(' ')[0]}! We’re so happy to have you. If there’s anything you need during your stay, just send us a message.</div><div class="bubble-meta" style="text-align:right">Welcome message · 9:00 AM</div><div class="bubble">${t.question}</div><div class="bubble-meta">${t.name.split(' ')[0]} · 12:42 PM</div>${approved?`<div class="bubble host">${esc((state.messages[t.id]||[])[0]||t.draft)}</div><div class="bubble-meta" style="text-align:right">${state.approved.includes(t.id)?'Approved by you':'Sent by AI'} · Demo</div>`:`<div class="ai-draft"><div class="flex between"><span class="eyebrow flex">${I('sparkle')} AI SUGGESTED REPLY</span>${badge('Your approval needed','blue')}</div><p id="draft-text">${t.draft}</p><div class="flex">${btn('Approve & send','approve','check','btn-primary',`data-id="${t.id}"`)}${btn('Edit','edit-draft','edit')}${btn('Take over','take-over')}</div></div>`}${(state.messages[t.id]||[]).slice(approved?1:0).map(m=>`<div class="bubble host">${esc(m)}</div>`).join('')}</div><form class="composer" data-form="send-message"><div class="compose-box"><input class="input" name="message" placeholder="Write a personal reply…" aria-label="Your reply" required autocomplete="off"><button class="btn btn-primary" aria-label="Send reply">${I('arrow')}</button></div><small class="muted" style="display:block;margin-top:8px">${state.takeover===t.id?'You’re managing this conversation.':'Replies stay in this demo workspace.'}</small></form></div><aside class="context-sidebar"><div class="eyebrow">Guest details</div><h3>${t.name}</h3><p style="font-size:11px">${t.channel} guest · 2 previous stays</p><div class="divider"></div><div class="eyebrow">Reservation</div><div class="context-pair"><span>Property</span><b>${prop(t.p).name}</b></div><div class="context-pair"><span>Dates</span><span>${t.date}</span></div><div class="context-pair"><span>Guests</span><span>${t.id===2?'4':'2'} adults</span></div><div class="context-pair"><span>Status</span>${badge('Confirmed','green')}</div><div class="divider"></div><div class="eyebrow">Knowledge sources</div><h3 class="flex">${I('file')} House manual</h3><p style="font-size:11px;line-height:1.8">Checkout is at 11:00 AM. Late checkout is subject to turnover availability and host approval.</p><button class="text-btn" data-property="${t.p}" style="margin-top:12px">View property ${I('arrow')}</button><div class="divider"></div><span class="eyebrow">AI confidence</span><div class="flex between" style="margin:12px 0;font-size:12px"><span>Based on property sources</span><b>98%</b></div><div class="progress"><span style="width:98%"></span></div></aside></section>${footer()}`}
function taskCard(t){return `<article class="task-card" draggable="true" data-task-id="${t.id}"><div class="flex between">${badge(t.type,t.type==='Turnover'?'blue':'')}<button class="icon-btn" data-action="open-task" data-id="${t.id}" aria-label="Task details">${I('chevron')}</button></div><h3>${t.name}</h3><p>${prop(t.p).name}</p><div class="task-time">${I('clock')}${t.time}</div><div class="task-person flex"><div class="avatar">${t.person.split(' ').map(x=>x[0]).join('')}</div><span class="grow">${esc(t.person)}</span><button class="icon-btn" data-action="reassign" data-id="${t.id}" aria-label="Reassign task">${I('edit')}</button></div><div class="key-row"><span class="flex">${I('key')}<span class="key">${t.code}</span></span><button class="icon-btn" data-action="copy" data-value="${t.code}" aria-label="Copy lock code">${I('copy')}</button></div><div class="task-actions">${btn(t.status==='Done'?'Reopen':t.status==='To do'?'Start task':'Mark done','task-status',t.status==='Done'?'sync':'check',t.status==='In progress'?'btn-primary':'',`data-id="${t.id}"`)}${btn('Message','message-cleaner','message','',`data-id="${t.id}"`)}</div></article>`}
function tasks(){const ts=state.tasks.filter(t=>selectedProperty==='all'||t.p===selectedProperty);return `${pageHeader('Good stays start behind the scenes.','Every turnover, every detail. Taken care of.',btn('Create task','new-task','plus','btn-primary'))}<div class="toolbar"><div class="segment">${['Board','Timeline','List'].map(v=>`<button class="${taskView===v?'selected':''}" data-action="task-view" data-view="${v}">${v}</button>`).join('')}</div><span class="muted" style="font-size:12px">${ts.filter(t=>t.status==='Done').length} of ${ts.length} tasks complete · Today</span></div>${taskView==='Board'?`<div class="kanban">${['To do','In progress','Done'].map((s,i)=>`<section class="kanban-col" data-drop="${s}"><div class="kanban-title"><i class="green-dot" style="background:${['#9caaa7','var(--blue)','#6ba987'][i]}"></i>${s}<span class="count">${ts.filter(t=>t.status===s).length}</span></div>${ts.filter(t=>t.status===s).map(taskCard).join('')||'<div class="empty"><p>All clear here.</p></div>'}</section>`).join('')}</div>`:`<section class="panel">${ts.map(t=>`<div class="list-row"><span class="schedule-icon">${I(t.type==='Turnover'?'sparkle':'task')}</span><div class="grow"><b>${t.name}</b><p>${prop(t.p).name} · ${t.person} · ${t.time}</p></div>${badge(t.status,t.status==='Done'?'green':'blue')}${btn('Details','open-task','chevron','',`data-id="${t.id}"`)}</div>`).join('')}</section>`}${footer()}`}
function propertiesPage(){return `${pageHeader('Distinctive places. Effortless operations.','Every property has a story. Keep every detail in one place.',btn('Add property','add-property','plus','btn-primary'))}<div class="toolbar"><span class="muted">${listProps().length} properties · 9 connected channels</span>${btn('Channel health','channels','sync')}</div><div class="property-grid property-list-grid">${listProps().map(propertyCard).join('')}</div><section class="panel" style="margin-top:26px"><div class="panel-heading"><h2>A healthier portfolio</h2>${badge('Co-pilot insight','blue')}</div><div class="feature-row">${I('sparkle')}<div class="grow"><h3>Your guests keep asking about local recommendations.</h3><p>Add your favorite coffee shops to the Pine & Still manual so AI can give more personal answers.</p></div><button class="icon-btn" data-property="cabin" aria-label="View Pine and Still">${I('arrow')}</button></div></section>${footer()}`}
function propertyPage(){const p=prop(activeProperty);return `${pageHeader(p.name,p.place,btn('Edit property','edit-property','edit'))}<div class="tabs">${['Overview','Channels & sync','House manual','Pricing','Access & devices','History'].map(t=>`<button class="${propertyTab===t?'selected':''}" data-action="property-tab" data-tab="${t}">${t}</button>`).join('')}</div>${propertyTab==='Overview'?`<section class="panel property-detail-hero"><img src="${p.image||'desert.jpg'}" alt="${p.name}"><div class="property-summary">${badge(p.status,'green')}<h2>A place to feel at home.</h2><p>${p.beds} bedrooms · ${p.beds+1} beds · ${p.beds*2} guests</p><div class="summary-numbers"><div><b>${p.occupancy}%</b><small>September occupancy</small></div><div><b>4.98</b><small>Guest rating</small></div></div><div class="divider"></div><div class="flex muted" style="font-size:11px">${I('pin')}${p.address}</div></div></section><div class="setting-grid"><section class="panel"><div class="panel-heading"><h2>Stay details</h2></div>${[['Current guest',p.guests],['Check-in','3:00 PM'],['Check-out','11:00 AM'],['Cleaner','Maria Santos'],['Time zone','America/Los_Angeles']].map(([a,b])=>`<div class="setting-row"><p>${a}</p><b style="font-size:12px">${b}</b></div>`).join('')}</section><section class="panel"><div class="panel-heading"><h2>Operational health</h2>${badge('Excellent','green')}</div>${[['Calendar sync','All 3 channels connected'],['AI knowledge','8 manual sections ready'],['Smart lock','Online · Battery 84%'],['Next turnover','Assigned and confirmed']].map(([a,b])=>`<div class="list-row">${I('check')}<div><b>${a}</b><p>${b}</p></div></div>`).join('')}</section></div>`:propertyTab==='Channels & sync'?channelsPanel():propertyTab==='House manual'?`<section class="panel"><div class="panel-heading"><h2>House manual</h2>${badge('AI-ready knowledge','blue')}</div><form data-form="manual" style="padding:24px"><p style="font-size:12px;margin-bottom:20px">Your guest-facing details are the source for accurate AI replies.</p><label class="field">Property guide<textarea name="manual" style="min-height:340px">${esc(state.manuals[p.id]||`WELCOME TO ${p.name.toUpperCase()}\n\nCHECK-IN & CHECKOUT\nCheck-in after 3:00 PM. Checkout by 11:00 AM. Special timing requires host approval.\n\nWI-FI\nNetwork: ${p.name.replaceAll(' ','')}_Guest\nPassword: WelcomeHome2026\n\nPARKING\nTwo complimentary spaces in the driveway. Please keep the neighbor’s access clear.\n\nHOUSE RULES\nQuiet hours: 10 PM – 8 AM. No parties or smoking indoors.\n\nLOCAL FAVORITES\nFresh coffee, scenic walks, and dinner recommendations are included in the welcome guide.\n\nEMERGENCIES\nFor an immediate emergency, call local emergency services. Contact your host for property support.`)}</textarea></label><button class="btn btn-primary">${I('check')}Save manual</button></form></section>`:propertyTab==='Pricing'?`<section class="panel"><div class="panel-heading"><h2>Pricing rules & guest extras</h2>${badge('Host-controlled','blue')}</div><form data-form="pricing" style="padding:24px"><div class="form-grid">${field('Minimum nightly rate ($)','min','number',state.pricing?.[p.id]?.min||175,'min="1" required')}${field('Cleaning fee ($)','cleaning','number',state.pricing?.[p.id]?.cleaning||120,'min="0" required')}${field('Early check-in ($)','early','number',state.pricing?.[p.id]?.early||35,'min="0" required')}${field('Late checkout ($)','late','number',state.pricing?.[p.id]?.late||40,'min="0" required')}</div><p style="margin-bottom:20px;font-size:12px">Suggestions remain subject to your minimum rate. Special requests always need approval.</p><button class="btn btn-primary">Save pricing rules</button></form></section>`:propertyTab==='Access & devices'?`<section class="panel"><div class="panel-heading"><h2>Access & devices</h2>${badge('1 device online','green')}</div><div class="list-row"><span class="automation-icon">${I('key')}</span><div class="grow"><b>Yale Assure · Front door</b><p>Battery 84% · Last activity 12 minutes ago</p></div>${badge('Online','green')}</div><div class="setting-row"><div><h3>Guest access code</h3><p>Active for the current stay only</p></div><div class="flex"><span class="key">${p.code}</span><button class="icon-btn" data-action="copy" data-value="${p.code}" aria-label="Copy code">${I('copy')}</button></div></div><div class="setting-row"><div><h3>Generate a new code</h3><p>Preview a unique access code for the next guest.</p></div>${btn('Generate','generate-code','key')}</div><div class="setting-row"><div><h3>Connect another device</h3><p>Yale, August, and Schlage integration setup.</p></div>${btn('Connect','device','plus')}</div></section>`:`<section class="panel"><div class="panel-heading"><h2>Property history</h2>${btn('Export','export','download')}</div>${[['Today, 12:58 PM','Calendar sync complete','3 connected channels · No conflicts'],['Today, 12:52 PM','AI answered a Wi-Fi question','House manual · 98% confidence'],['Sep 12, 3:12 PM','Guest checked in','Smart lock access confirmed'],['Sep 12, 1:34 PM','Turnover completed','Photos submitted by Maria Santos']].map(([t,a,b])=>`<div class="list-row">${I('clock')}<div class="grow"><b>${a}</b><p>${b}</p></div><small class="muted">${t}</small></div>`).join('')}</section>`}${footer()}`}
function channelsPanel(){return `<section class="panel"><div class="panel-heading"><h2>Connected channels</h2>${btn('Sync now','sync','sync')}</div>${['Airbnb','Vrbo','Booking.com','Expedia'].map((ch,i)=>`<div class="list-row"><span class="integration-logo" style="color:${['#df807b','#6c82b4','#5482af','#a89056'][i]}">${ch[0]}</span><div class="grow"><b>${ch}</b><p>${state.connected.includes(ch)?'Last synced 2 minutes ago · No conflicts':'Connect an iCal feed to protect your dates'}</p></div>${badge(state.connected.includes(ch)?'Connected':'Not connected',state.connected.includes(ch)?'green':'')}${btn(state.connected.includes(ch)?'Manage':'Connect','connect','link','',`data-channel="${ch}"`)}</div>`).join('')}<div class="setting-row"><div><h3>Intelligent availability protection</h3><p>Imported bookings are excluded from their origin channel’s export feed to prevent loops.</p></div>${I('shield')}</div></section>`}
function automations(){return `${pageHeader('Less managing. More living.','Thoughtful automations that work quietly in the background.',btn('Ask co-pilot','copilot','sparkle','btn-primary'))}<section class="hero" style="min-height:160px;margin-bottom:25px"><div><div class="eyebrow">${I('bolt')} AUTONOMOUS OPERATIONS</div><h2>${state.autopilot?'Autopilot is on. You’re in control.':'Autopilot is taking a pause.'}</h2><p>Routine details, handled. Important decisions, always yours.</p></div><div class="stack" style="align-items:center">${toggle('autopilot',state.autopilot,'root')}<small style="color:#aab4b6">${state.autopilot?'Active':'Paused'}</small></div></section><div class="automation-grid">${[['sync','sync','Calendar protection','Keep availability aligned across every connected booking channel.','New booking','Block other channels','142 dates protected'],['replies','sparkle','Thoughtful guest replies','Answer routine questions using your property manuals, in the guest’s language.','Guest question','AI reply','86 replies this month'],['turnover','task','Seamless turnovers','Create cleaning tasks with access codes and notify the right person.','Guest checkout','Assign cleaner','24 turnovers scheduled'],['arrival','login','A warm welcome','Deliver check-in instructions, directions, and a personal welcome.','24h before arrival','Send guide','38 happy arrivals'],['upsells','dollar','Little extras','Offer early check-in, late checkout, or a mid-stay refresh.','72h before arrival','Offer extras','Host approval required'],['reviews','heart','Keep the good going','Send a thoughtful thank-you and invite guests to share their experience.','24h after checkout','Request review','4.98 average rating']].map(([key,icon,title,desc,trigger,action,stat])=>`<section class="panel automation-card"><div class="automation-top"><span class="automation-icon">${I(icon)}</span>${toggle(key,state.rules[key])}</div><h3>${title}</h3><p>${desc}</p><div class="workflow"><span>${trigger}</span>${I('arrow')}<span>${action}</span></div><div class="flex between"><small class="muted">${stat}</small><button class="text-btn" data-action="rule-details" data-rule="${key}">Configure ${I('chevron')}</button></div></section>`).join('')}</div><section class="panel" style="margin-top:25px"><div class="panel-heading"><h2>Your guardrails</h2>${badge('Human judgment first','green')}</div>${[['shield','Special requests & discounts','AI drafts a response. You approve, edit, or take over.'],['bell','Emergencies & complaints','Escalate immediately and notify the host.'],['calendar','Reservation changes','Always require a host review before any dates change.']].map(([i,t,d])=>`<div class="feature-row">${I(i)}<div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</section>${footer()}`}
function insights(owner=false){return `${pageHeader(owner?'Your portfolio, at a glance.':'A clearer picture of your progress.',owner?'Owner view · September 2026':'The numbers behind memorable stays.',owner?'':btn('Export report','export','download'))}${owner?'<div class="owner-banner">'+I('shield')+'Owner preview · Read-only portfolio performance</div>':''}<section class="metrics">${[['$27,570','September revenue','+12.4%'],['87.3%','Portfolio occupancy','+5.2%'],['4.98','Average guest rating','+0.06'],['32.5h','Time saved this month','+8.4h']].map(([v,t,b])=>`<div class="metric"><div class="metric-title">${t}${I(t.includes('revenue')?'dollar':t.includes('rating')?'heart':'chart')}</div><div class="metric-value">${v}</div><div class="metric-bottom"><span class="mini-pill">${b}</span>vs. last month</div></div>`).join('')}</section><div class="finance-grid"><section class="panel chart-panel"><div class="flex between"><div><h2>Revenue over time</h2><p style="font-size:11px;margin-top:4px">April – September 2026</p></div>${badge('+12.4% this month','green')}</div><div class="stat-trend" role="img" aria-label="Revenue rises from $16,420 in April to $27,570 in September">${[59,68,62,80,88,100].map((h,i)=>`<i title="${['Apr $16,420','May $18,750','Jun $17,130','Jul $22,100','Aug $24,530','Sep $27,570'][i]}" style="height:${h}%;background:${i===5?'var(--blue)':''}"></i>`).join('')}</div><div class="chart-labels">${['Apr','May','Jun','Jul','Aug','Sep'].map(m=>`<span>${m}</span>`).join('')}</div></section><section class="panel chart-panel"><h2>Your operations dividend</h2><div class="insight-value">32.5 <span class="muted" style="font-size:16px">hours back</span></div><p style="font-size:12px">More room for the things that matter.</p><div class="divider"></div>${[['Guest messaging',16.8,52],['Calendar management',9.2,28],['Cleaning coordination',6.5,20]].map(([a,b,p])=>`<div style="margin:18px 0"><div class="flex between" style="font-size:11px;margin-bottom:8px"><span>${a}</span><b>${b}h</b></div><div class="progress"><span style="width:${p}%"></span></div></div>`).join('')}</section></div><section class="panel" style="margin-top:24px"><div class="panel-heading"><h2>Performance by property</h2>${badge('September 2026')}</div><div class="table-scroll"><table><thead><tr><th>Property</th><th>Revenue</th><th>Occupancy</th><th>Expenses</th><th>Net income</th><th>Guest rating</th></tr></thead><tbody>${listProps().map((p,i)=>`<tr><td><b>${p.name}</b><p style="font-size:10px;margin-top:3px">${p.place}</p></td><td>${money(p.revenue)}</td><td>${p.occupancy}%</td><td>${money([2170,3210,1820][i]||1500)}</td><td>${money(p.revenue-([2170,3210,1820][i]||1500))}</td><td>★ ${[4.99,4.98,4.96][i]||4.98}</td></tr>`).join('')}</tbody></table></div></section>${!owner?`<div class="setting-grid" style="margin-top:24px"><section class="panel"><div class="panel-heading"><h2>Cleaner performance</h2>${btn('Payouts','payouts','dollar')}</div>${[['Maria Santos','16 turnovers · 100% on time','4.99'],['Alex Rivera','8 turnovers · 98% on time','4.96']].map(([n,s,r])=>`<div class="list-row"><div class="avatar">${n.split(' ').map(x=>x[0]).join('')}</div><div class="grow"><b>${n}</b><p>${s}</p></div>${badge('★ '+r,'green')}</div>`).join('')}</section><section class="panel"><div class="panel-heading"><h2>Looking ahead</h2>${badge('Co-pilot','blue')}</div><div class="feature-row">${I('settings')}<div><h3>Schedule an AC filter check</h3><p>Two guests mentioned cooling at Coastal Retreat. A preventive inspection may help.</p><button class="text-btn" style="margin-top:10px" data-action="new-task">Create inspection ${I('arrow')}</button></div></div></section></div>`:''}${footer()}`}
function settings(){return `${pageHeader('Make yourself at home.','Your workspace, your preferences, your way.',btn('Owner preview','owner','shield'))}<div class="setting-grid"><div><section class="panel"><div class="panel-heading"><h2>Workspace</h2></div><form data-form="workspace" style="padding:22px">${field('Workspace name','name','text',state.workspaceName||'My workspace')}${field('Display name','displayName','text',state.displayName||'Praneeth Narala')}<label class="field">Time zone<select name="timezone"><option>America/Los_Angeles</option><option>America/Chicago</option><option>America/New_York</option><option>Europe/London</option></select></label><button class="btn btn-primary">Save preferences</button></form></section><section class="panel" style="margin-top:23px"><div class="panel-heading"><h2>Notifications</h2></div>${[['email','Email digest','A calm summary of your day.'],['push','Operational alerts','Arrivals, turnovers, and tasks.'],['emergency','Priority escalation','Guest complaints and emergencies.']].map(([k,t,d])=>`<div class="setting-row"><div><h3>${t}</h3><p>${d}</p></div>${toggle(k,state.settings[k],'settings')}</div>`).join('')}</section></div><div><section class="panel"><div class="panel-heading"><h2>Appearance</h2></div><div class="setting-row"><div><h3>Dark mode</h3><p>A quieter workspace after hours.</p></div><button class="toggle ${state.theme==='dark'?'on':''}" role="switch" aria-label="Dark mode" aria-checked="${state.theme==='dark'}" data-action="theme"></button></div></section><section class="panel" style="margin-top:23px"><div class="panel-heading"><h2>Workspace tools</h2></div>${[['channels','link','Channel connections','Manage your booking platform feeds'],['team','users','Team & access','Hosts, cleaners, and property owners'],['templates','message','Message templates','Thoughtful replies, ready to personalize'],['export','download','Export demo data','Download a snapshot of this workspace'],['reset','sync','Reset demo workspace','Restore the original demo experience']].map(([a,i,t,s])=>`<button class="setting-row" style="width:100%;text-align:left" data-action="${a}">${I(i)}<div class="grow"><h3>${t}</h3><p>${s}</p></div>${I('chevron')}</button>`).join('')}</section><p style="font-size:11px;margin-top:19px">Interactive demo · Changes stay in this browser. External integrations and AI responses are simulated.</p></div></div>${footer()}`}
function cleaner(){const jobs=state.tasks.filter(t=>t.person==='Maria Santos');return `${pageHeader('Cleaner portal','A focused, mobile-first experience for your on-site team.',badge('Previewing as Maria Santos','blue'))}<div class="phone-frame"><div class="phone-top"><b>9:41</b><span>●●● ▰</span></div><p class="eyebrow" style="font-size:10px;margin-bottom:8px">MONDAY, SEPTEMBER 14</p><h2>Morning, Maria.</h2><p style="font-size:12px;margin-top:6px">${jobs.filter(t=>t.status!=='Done').length} jobs to make someone feel at home.</p>${jobs.map(t=>`<section class="cleaner-job"><img src="${prop(t.p).image||'desert.jpg'}" alt="${prop(t.p).name}"><div class="cleaner-job-content"><div class="flex between"><h3>${prop(t.p).name}</h3>${badge(t.status,t.status==='Done'?'green':'blue')}</div><p>${t.name} · ${t.time}</p>${btn('View directions','directions','pin','',`data-id="${t.id}"`)}${btn('Reveal access code','reveal','key','',`data-id="${t.id}"`)}<div class="divider"></div>${['Fresh linens & towels','Kitchen & bathrooms','Restock essentials','Final walkthrough'].map((x,i)=>`<label class="cleaner-check"><input type="checkbox" data-check="${t.id}-${i}" ${state.checks?.[t.id+'-'+i]||t.status==='Done'?'checked':''}>${x}</label>`).join('')}<div class="photo-grid">${(state.photos[t.id]||[]).map(src=>`<img src="${src}" alt="Cleaning proof">`).join('')}</div><label class="btn" style="cursor:pointer">${I('camera')}Add before / after photos<input type="file" accept="image/*" multiple data-photo-task="${t.id}" style="display:none"></label>${btn('Add a note','cleaner-note','message','',`data-id="${t.id}"`)}${btn(t.status==='Done'?'Completed':'Complete job','complete-cleaner','check','btn-primary',`data-id="${t.id}" ${t.status==='Done'?'disabled':''}`)}<p class="checklist-note">Checklist and photos are saved locally in this demo.</p></div></section>`).join('')}</div>${footer()}`}
Object.assign(pages,{calendar,inbox,tasks,properties:propertiesPage,property:propertyPage,automations,insights:()=>insights(),settings,cleaner,owner:()=>insights(true)});
properties[1].image='coast.jpg';properties[2].image='cabin.jpg';
const taskById=e=>state.tasks.find(t=>t.id===+e.dataset.id);
Object.assign(actions,{
'prev-week':()=>{calendarOffset-=14;render()},'next-week':()=>{calendarOffset+=14;render()},'calendar-today':()=>{calendarOffset=0;render()},sync:()=>{toast('Checking connected demo channels…');setTimeout(()=>toast('All calendars are up to date. No conflicts found.'),900)},
'new-block':e=>modal('Make a little room.',`<form id="block-form" data-form="block">${propertySelect('property',e?.dataset.p||activeProperty)}<div class="form-grid">${field('From','from','date',e?.dataset.date||'2026-09-26','required')}${field('Until (checkout day)','to','date','2026-09-28','required')}</div>${field('Reason','reason','text','Owner stay','required maxlength="80"')}<p>These dates will be unavailable in your demo calendar. Existing reservations are protected.</p></form>`,btn('Cancel','close')+'<button class="btn btn-primary" type="submit" form="block-form">Block dates</button>'),
booking:e=>{const b=[...bookings,...state.blocks.map(x=>({...x,guest:x.reason,channel:'Manual'}))].find(x=>String(x.id)===e.dataset.id);if(!b)return;modal(b.channel==='Manual'?'Calendar block':'Reservation details',`${badge(b.channel==='Manual'?'Manually blocked':'Confirmed','green')}<h2 style="margin:20px 0 4px">${esc(b.guest)}</h2><p>${prop(b.p).name} · ${b.channel}</p><div class="divider"></div>${[['Check-in',dateLabel(b.from)],['Check-out',dateLabel(b.to)],['Guests',b.guests||'—'],['Reservation total',b.total?money(b.total):'—'],['Calendar protection',b.channel==='Manual'?'Manual block':'Other channels blocked automatically'],['Turnover',b.channel==='Manual'?'Not required':'Assigned · Access code ready']].map(([a,c])=>`<div class="context-pair"><span>${a}</span><b>${c}</b></div>`).join('')}`,b.channel==='Manual'?btn('Remove block','remove-block','','',`data-id="${b.id}"`):btn('View property','booking-property','home','btn-primary',`data-p="${b.p}"`))},
'booking-property':e=>{activeProperty=e.dataset.p;propertyTab='Overview';close();go('property')},'remove-block':e=>{state.blocks=state.blocks.filter(b=>String(b.id)!==e.dataset.id);save();close();render();toast('Block removed. Those dates are available again.')},
thread:e=>{selectedThread=+e.dataset.id;render()},approve:e=>{const id=+e.dataset.id,t=threads.find(t=>t.id===id);const reply=document.getElementById('draft-edit')?.value||t.draft;if(!reply.trim())return toast('Add a reply before approving.');state.approved=[...new Set([...state.approved,id])];state.messages[id]=[reply,...(state.messages[id]||[])];save();render();toast('Reply approved and added to the demo conversation.')},'edit-draft':()=>{const t=threads.find(t=>t.id===selectedThread);document.getElementById('draft-text').outerHTML=`<textarea id="draft-edit" aria-label="Edit AI draft">${esc(t.draft)}</textarea>`;document.getElementById('draft-edit').focus()},'take-over':()=>{state.takeover=selectedThread;save();render();document.querySelector('[name=message]').focus();toast('You’re managing this conversation.')},
'new-task':()=>modal('Give every detail a place.',`<form id="task-form" data-form="task">${field('Task name','name','text','','placeholder="e.g. Restock bathroom essentials" required maxlength="90"')}${propertySelect()}<div class="form-grid"><label class="field">Task type<select name="type"><option>Turnover</option><option>Inspection</option><option>Restock</option><option>Maintenance</option><option>Mid-stay cleaning</option></select></label><label class="field">Assign to<select name="person"><option>Maria Santos</option><option>Alex Rivera</option><option>Unassigned</option></select></label></div>${field('Scheduled window','time','text','Tomorrow · 11:00 AM – 1:00 PM','required')}</form>`,btn('Cancel','close')+'<button class="btn btn-primary" form="task-form">Create task</button>'),
'open-task':e=>{const t=taskById(e);modal(t.name,`${badge(t.status,t.status==='Done'?'green':'blue')}<h3 style="margin-top:20px">${prop(t.p).name}</h3><p>${t.time}</p><div class="divider"></div><div class="context-pair"><span>Assigned to</span><b>${esc(t.person)}</b></div><div class="context-pair"><span>Type</span><b>${t.type}</b></div><div class="context-pair"><span>Access code</span><b class="key">${t.code}</b></div><p style="margin-top:18px">Prepare the property, complete the checklist, and add photo proof in the cleaner portal.</p>`,btn('Reassign','reassign','edit','',`data-id="${t.id}"`)+btn(t.status==='Done'?'Reopen':t.status==='To do'?'Start task':'Mark done','task-status','check','btn-primary',`data-id="${t.id}"`))},
'view-tasks':()=>go('tasks'),'task-view':e=>{taskView=e.dataset.view;render()},'task-status':e=>{const t=taskById(e);t.status=t.status==='To do'?'In progress':t.status==='In progress'?'Done':'To do';save();close();render();toast(`${t.name}: ${t.status.toLowerCase()}.`)},reassign:e=>{const t=taskById(e);modal('The right person for the job.',`<form data-form="reassign" id="reassign-form"><input type="hidden" name="id" value="${t.id}"><p style="margin-bottom:18px">${t.name} · ${prop(t.p).name}</p><label class="field">Assign to<select name="person">${['Maria Santos','Alex Rivera','Unassigned'].map(n=>`<option ${t.person===n?'selected':''}>${n}</option>`).join('')}</select></label></form>`,'<button class="btn btn-primary" form="reassign-form">Save assignment</button>')},
'message-cleaner':e=>{const t=taskById(e);modal(`Message ${esc(t.person.split(' ')[0])}`,`<form id="cleaner-message-form" data-form="cleaner-message"><input type="hidden" name="id" value="${t.id}"><label class="field">Your message<textarea name="message" required>Hi ${esc(t.person.split(' ')[0])}, a quick note about ${prop(t.p).name}: </textarea></label><p>Demo message preview · No SMS or WhatsApp message is sent.</p></form>`,'<button class="btn btn-primary" form="cleaner-message-form">Save message</button>')},
copy:async e=>{try{await navigator.clipboard.writeText(e.dataset.value);toast('Copied to clipboard.')}catch{modal('Copy this value',`<input class="input key" value="${esc(e.dataset.value)}" readonly aria-label="Value to copy">`)}},
'property-tab':e=>{propertyTab=e.dataset.tab;render()},channels:()=>modal('Every channel, in harmony.',channelsPanel(),'',true),connect:e=>modal(`${e.dataset.channel} connection`, `<form id="channel-form" data-form="channel"><input type="hidden" name="channel" value="${e.dataset.channel}">${propertySelect()}${field('Import calendar URL','url','url',state.feeds?.[e.dataset.channel]||'','placeholder="https://…/calendar.ics" required')}<p>Add the iCal link from your listing’s availability settings. Demo connections are stored locally.</p><div class="divider"></div><label class="field">Your demo export feed<input class="input" readonly value="https://demo.example/ical/${activeProperty}/${e.dataset.channel.toLowerCase().replace(/[^a-z]/g,'')}.ics"></label><p>Production export links become available when the sync backend is connected.</p></form>`,'<button class="btn btn-primary" form="channel-form">Save connection</button>'),
'add-property':()=>modal('A new place, a fresh start.',`<form id="property-form" data-form="property">${field('Property name','name','text','','required placeholder="e.g. The Lake House"')}${field('Location','place','text','','required placeholder="City, State"')}${field('Address','address','text','','required')}${field('Bedrooms','beds','number',2,'min="1" max="30" required')}</form>`,'<button class="btn btn-primary" form="property-form">Add property</button>'),
'edit-property':()=>{const p=prop(activeProperty);modal('Property details',`<form id="edit-property-form" data-form="edit-property">${field('Property name','name','text',p.name,'required')}${field('Location','place','text',p.place,'required')}${field('Address','address','text',p.address,'required')}${field('Bedrooms','beds','number',p.beds,'min="1" required')}</form>`,'<button class="btn btn-primary" form="edit-property-form">Save changes</button>')},
'toggle':e=>{if(e.dataset.group==='root')state.autopilot=!state.autopilot;else state[e.dataset.group][e.dataset.key]=!state[e.dataset.group][e.dataset.key];save();render();toast('Demo preferences updated.')},'generate-code':()=>{const code=String(Math.floor(1000+Math.random()*9000));modal('Your next guest’s access code',`<p>A fresh code, ready for your next stay.</p><div class="key" style="font-size:44px;text-align:center;padding:30px">${code}</div><p>This is a demo code. No smart lock has been changed.</p>`,btn('Copy code','copy','copy','btn-primary',`data-value="${code}"`))},device:()=>modal('Connect a smart lock',`<p>Select the device you’d like to connect.</p>${['Yale Assure','August Smart Lock','Schlage Encode'].map(n=>`<button class="command-item" data-action="device-info" data-device="${n}">${I('key')}${n}${I('chevron')}</button>`).join('')}`),'device-info':e=>modal(e.dataset.device,`<div class="empty">${I('key')}<h3>Ready for integration.</h3><p>The production setup will securely link your device account and create time-limited guest codes. This demo previews the device experience.</p></div>`),
'rule-details':e=>modal('Fine-tune your automation',`<form id="rule-form" data-form="rule"><input type="hidden" name="rule" value="${e.dataset.rule}"><label class="field">Applies to<select name="scope"><option>All properties</option>${properties.map(p=>`<option>${p.name}</option>`).join('')}</select></label><label class="field">Behavior<select name="mode"><option>Automatic with host guardrails</option><option>Draft for host approval</option><option>Notify host only</option></select></label>${field('Quiet hours begin','quiet','time','22:00')}<p>Emergencies and booking modifications always escalate to the host. Routine replies use your house manual.</p></form>`,'<button class="btn btn-primary" form="rule-form">Save automation</button>'),
copilot:()=>modal('A little help from your co-pilot.',`<div class="owner-banner">${I('sparkle')}Your portfolio, understood.</div><p>Try one of these questions, or write your own.</p><div class="command-list">${['Which properties need attention?','Summarize today’s operations','How is my portfolio performing?'].map(q=>`<button class="command-item" data-action="copilot-answer" data-question="${q}">${I('sparkle')}${q}</button>`).join('')}</div><form data-form="copilot"><div class="compose-box"><input class="input" name="question" required placeholder="Ask about your properties…" aria-label="Ask co-pilot"><button class="btn btn-primary" aria-label="Ask">${I('arrow')}</button></div></form><p style="font-size:10px;margin-top:12px">Demo co-pilot · Guided responses from this sample workspace.</p>`),
'copilot-answer':e=>copilotAnswer(e.dataset.question),templates:()=>modal('A thoughtful word, ready to go.',`${['Welcome & arrival','Wi-Fi & house essentials','Checkout reminder','Thank you & review request'].map((t,i)=>`<div class="list-row"><span class="automation-icon">${I('message')}</span><div class="grow"><b>${t}</b><p>${['A warm hello with everything for a smooth arrival.','The practical details that make a stay effortless.','A gentle reminder before the journey home.','Keep the conversation going after a great stay.'][i]}</p></div>${btn('Use','template-use','copy','',`data-template="${i}"`)}</div>`).join('')}`,'',true),'template-use':e=>{const templates=['Hi there! We’re excited to welcome you. Check-in is from 3 PM. Your access instructions will arrive before your stay. Let us know if you need anything.','You’ll find the Wi-Fi network and password in your house manual, along with parking details and our local recommendations.','We hope you’ve had a wonderful stay. A gentle reminder that checkout is at 11 AM tomorrow. Safe travels!','Thank you for staying with us! We’d love to hear about your experience. Your review helps future guests find their perfect stay.'];modal('Personalize your message',`<label class="field">Template<textarea id="template-copy">${templates[+e.dataset.template]}</textarea></label>`,btn('Copy template','copy-template','copy','btn-primary'))},'copy-template':()=>actions.copy({dataset:{value:document.getElementById('template-copy').value}}),
export:()=>{const rows=['Property,Revenue,Occupancy,Rating',...properties.map((p,i)=>`"${p.name.replaceAll('"','""')}",${p.revenue},${p.occupancy}%,${[4.99,4.98,4.96][i]||'—'}`)].join('\n');download('airbnb-automation-report.csv',rows,'text/csv');toast('Demo report exported.')},owner:()=>go('owner'),team:()=>modal('People behind great stays',`${[['PN','Praneeth Narala','Owner · Full workspace access'],['MS','Maria Santos','Cleaner · Assigned tasks only'],['AR','Alex Rivera','Cleaner · Assigned tasks only']].map(([a,n,r])=>`<div class="list-row"><span class="avatar">${a}</span><div><b>${n}</b><p>${r}</p></div></div>`).join('')}<p style="margin-top:20px">Invite flows and role permissions connect to authentication in the production app.</p>`),payouts:()=>modal('Cleaner payouts',`${[['Maria Santos','$1,920','16 completed turnovers'],['Alex Rivera','$960','8 completed turnovers']].map(([n,v,s])=>`<div class="list-row"><div class="grow"><b>${n}</b><p>${s}</p></div><b>${v}</b>${badge('Scheduled','blue')}</div>`).join('')}<p style="margin-top:20px">September payout summary · Demo only. No payment will be initiated.</p>`,btn('Export summary','export','download')),
reset:()=>modal('Start fresh?',`<p>This resets locally saved demo messages, tasks, calendar blocks, and settings. Your original demo workspace will be restored.</p>`,btn('Keep my changes','close')+btn('Reset demo','confirm-reset','sync','btn-primary')),'confirm-reset':()=>{state=structuredClone(defaults);save();location.hash='overview';location.reload()},reveal:e=>{const t=taskById(e);modal('You’re welcome in.',`<p>${prop(t.p).name} · Front door</p><div class="key" style="font-size:42px;text-align:center;padding:28px">${t.code}</div><p>Demo access code · Available during your assigned cleaning window.</p>`,btn('Copy code','copy','copy','btn-primary',`data-value="${t.code}"`))},directions:e=>{const p=prop(taskById(e).p);modal('Find your way.',`<h3>${p.name}</h3><p style="margin:10px 0 20px">${p.address}</p><p>Demo property address. Use the front driveway and enter through the main door. Keep the neighboring driveway clear.</p>`,btn('Copy address','copy','copy','btn-primary',`data-value="${esc(p.address)}"`))},'cleaner-note':e=>modal('Leave a note for the host.',`<form id="note-form" data-form="note"><input type="hidden" name="id" value="${e.dataset.id}"><label class="field">Property note<textarea name="note" placeholder="Anything the host should know?" required>${esc(state.notes?.[e.dataset.id]||'')}</textarea></label></form>`,'<button class="btn btn-primary" form="note-form">Save note</button>'),'complete-cleaner':e=>{const t=taskById(e);if(![0,1,2,3].every(i=>state.checks?.[t.id+'-'+i]))return toast('Finish the four checklist items before completing.');t.status='Done';save();render();toast('Great work. This property is guest-ready.')}
});
function download(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function copilotAnswer(q){const lower=q.toLowerCase();const answer=/perform|revenue|income/.test(lower)?'Your portfolio earned $27,570 in September, up 12.4%. Coastal Retreat leads at $12,800. Occupancy is 87.3%, and the guest rating is 4.98.':/attention|weekend|request/.test(lower)?'The Desert House has a late-checkout request from Sarah. Emily is asking about early check-in at Coastal Retreat. Pine & Still needs essentials restocked before the next arrival.':'Today, Maria is preparing Coastal Retreat for Emily’s arrival. Pine & Still has a restock task, and all 9 demo channels are in sync. Your AI has handled routine guest questions, leaving special requests for your approval.';modal('Your co-pilot',`<div class="bubble">${esc(q)}</div><div class="ai-draft"><span class="eyebrow flex">${I('sparkle')} WORKSPACE SUMMARY</span><p>${answer}</p></div><p style="font-size:10px;margin-top:16px">Guided demo response, based on the sample portfolio.</p>`,btn('View operations','view-tasks','task','btn-primary'))}
document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const data=Object.fromEntries(new FormData(form));switch(form.dataset.form){case'block':{if(data.to<=data.from)return toast('Choose an end date after the start date.');if([...bookings,...state.blocks].some(b=>b.p===data.property&&data.from<b.to&&data.to>b.from))return toast('These dates overlap an existing reservation or block.');state.blocks.push({id:Date.now(),p:data.property,from:data.from,to:data.to,reason:data.reason});close();go('calendar');toast('Dates blocked in your demo calendar.');break}case'task':state.tasks.push({id:Date.now(),p:data.property,name:data.name,type:data.type,person:data.person,time:data.time,status:'To do',code:prop(data.property).code});close();go('tasks');toast('Your new task is ready.');break;case'reassign':state.tasks.find(t=>t.id===+data.id).person=data.person;close();render();toast('Assignment updated.');break;case'send-message':if(!data.message.trim())return;state.messages[selectedThread]=[...(state.messages[selectedThread]||[]),data.message];render();toast('Reply added to this demo conversation.');break;case'manual':state.manuals[activeProperty]=data.manual;toast('House manual saved. AI knowledge preview updated.');break;case'pricing':state.pricing={...state.pricing,[activeProperty]:data};toast('Pricing guardrails saved.');break;case'workspace':state.workspaceName=data.name;state.displayName=data.displayName;state.timezone=data.timezone;render();toast('Workspace preferences saved.');break;case'channel':state.connected=[...new Set([...state.connected,data.channel])];state.feeds={...state.feeds,[data.channel]:data.url};close();render();toast('Demo channel connection saved.');break;case'property':{const p={id:'property-'+Date.now(),name:data.name,place:data.place,address:data.address,beds:+data.beds,occupancy:0,revenue:0,status:'Ready to set up',guests:'No guests yet',image:'desert.jpg',code:'—',color:'#a9b4aa'};properties.push(p);state.extraProperties=[...(state.extraProperties||[]),p];close();go('properties');toast('Property added. Connect a channel to get started.');break}case'edit-property':{const p=prop(activeProperty);Object.assign(p,{name:data.name,place:data.place,address:data.address,beds:+data.beds});state.propertyEdits={...state.propertyEdits,[p.id]:{name:p.name,place:p.place,address:p.address,beds:p.beds}};close();render();toast('Property details saved.');break}case'rule':state.ruleConfig={...state.ruleConfig,[data.rule]:data};close();toast('Automation preferences saved.');break;case'cleaner-message':state.cleanerMessages=[...(state.cleanerMessages||[]),data];close();toast('Message saved in the demo.');break;case'note':state.notes={...state.notes,[data.id]:data.note};close();toast('Property note saved.');break;case'copilot':copilotAnswer(data.question);break}save()});
document.addEventListener('change',async e=>{if(e.target.id==='calendar-property'){selectedProperty=e.target.value;render()}if(e.target.id==='inbox-filter'){inboxFilter=e.target.value;render()}if(e.target.dataset.check){state.checks={...state.checks,[e.target.dataset.check]:e.target.checked};save()}if(e.target.dataset.photoTask){const id=e.target.dataset.photoTask;const files=[...e.target.files].filter(f=>f.type.startsWith('image/'));if(!files.length)return;const photos=[];for(const f of files.slice(0,3)){if(f.size>2*1024*1024){toast('Choose photos smaller than 2 MB for this demo.');continue}photos.push(await new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.readAsDataURL(f)}))}state.photos[id]=[...(state.photos[id]||[]),...photos].slice(0,6);save();render();toast('Cleaning photos added to your demo.')}});
document.addEventListener('dragstart',e=>{const t=e.target.closest('[data-task-id]');if(t)e.dataTransfer.setData('text/plain',t.dataset.taskId)});document.addEventListener('dragover',e=>{if(e.target.closest('[data-drop]'))e.preventDefault()});document.addEventListener('drop',e=>{const col=e.target.closest('[data-drop]');if(!col)return;e.preventDefault();const t=state.tasks.find(t=>t.id===+e.dataTransfer.getData('text/plain'));if(t){t.status=col.dataset.drop;save();render();toast('Task moved to '+t.status.toLowerCase()+'.')}});
if(state.extraProperties)properties.push(...state.extraProperties);for(const p of properties)if(state.propertyEdits?.[p.id])Object.assign(p,state.propertyEdits[p.id]);
render();
